    private void a_bActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_a_bActionPerformed
       db_conn dd=new db_conn();
        try
       {   
           dd.query="select * from admin where username=?";
           dd.a.add(a_user.getText());
           ResultSet rs=dd.select();
           if(rs.next()&& (rs.getString("password").equals(a_pass.getText())))
           {
               JOptionPane.showMessageDialog(null,"Sucsessfully Loged In","Done",JOptionPane.INFORMATION_MESSAGE);
                   DB db=new DB();
                   db.setVisible(true);
                   this.setVisible(false);
           }
           else
           {
               JOptionPane.showMessageDialog(null,"Invalid","Invalid User",JOptionPane.WARNING_MESSAGE);
           }
       }
       catch(NullPointerException e){
           JOptionPane.showMessageDialog(null,"Connection Error");
       }
       catch(SQLException | HeadlessException e)
       {
           System.out.println(e);
       }
    }//GEN-LAST:event_a_bActionPerformed

